"""Liveness and readiness endpoints. Generated by `eos scaffold docker-python` (FastAPI). Wire it in:
    from app.health import router as health_router
    app.include_router(health_router)
/healthz: the process is up (no dependencies; used by the container HEALTHCHECK).
/readyz:  dependencies answer; add a cheap check per dependency (DB `SELECT 1`, Redis PING) in `CHECKS`.
Each check gets CHECK_TIMEOUT seconds: a hung dependency must make the probe fail, not hang.
Tested by tests/test_health.py. Why: .eos/packs/ref/ops/platforms.md (probes).
"""

import asyncio
from collections.abc import Awaitable, Callable

from fastapi import APIRouter, Response, status

router = APIRouter(tags=["health"])
CHECKS: dict[str, Callable[[], Awaitable[None]]] = {}
CHECK_TIMEOUT = 2.0


@router.get("/healthz", include_in_schema=False)
async def healthz() -> dict[str, str]:
    return {"status": "ok"}


@router.get("/readyz", include_in_schema=False)
async def readyz(response: Response) -> dict[str, str]:
    result: dict[str, str] = {}
    for name, check in CHECKS.items():
        try:
            await asyncio.wait_for(check(), CHECK_TIMEOUT)
            result[name] = "ok"
        except Exception:  # noqa: BLE001 - a readiness probe reports any failure, never its text
            result[name] = "fail"
            response.status_code = status.HTTP_503_SERVICE_UNAVAILABLE
    return result
